      const pos = posEst;
      const v = velEst;

      if (obs.t > 0.015) {
        const axRaw = (v.x - prevVel.x) / dt;
        const ayRaw = (v.y - prevVel.y) / dt;
        const azRaw = (v.z - prevVel.z) / dt;

        const alpha = 0.14;
        dxEst = clamp(dxEst + alpha * (axRaw - prevCmd.x - dxEst), -7.5, 7.5);
        dzEst = clamp(dzEst + alpha * (azRaw - prevCmd.z - dzEst), -7.5, 7.5);

        if (obs.t > 0.05 && prevCmd.y > 6.0 && Math.abs(ayRaw) < 15.0) {
          const b0Meas = ((ayRaw + g + 0.55 * v.y) / prevCmd.y) * b0Est;
          const b0Clamped = clamp(b0Meas, 13.5, 27.5);
          const b0Rate = obs.t < 1.5 ? 0.05 : 0.008;
          b0Est += b0Rate * (b0Clamped - b0Est);
        }
      }
      prevVel.x = v.x;
      prevVel.y = v.y;
      prevVel.z = v.z;

      if (obs.gateIndex !== prevGateIndex) {
        prevGate = currentGateCache;
        prevGateIndex = obs.gateIndex;
        phase = obs.gateIndex < 3 ? "align" : "padApproach";
        settle = 0;
      }
      if (obs.nextGate) {
        currentGateCache = obs.nextGate.centre;
      }

      let target;
      let velTarget = { x: 0, y: 0, z: 0 };

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (prevGate && pos.x < prevGate.x + 0.15 && phase === "align") {
          target = { x: prevGate.x + 0.35, y: prevGate.y, z: prevGate.z };
          velTarget = { x: 0.75, y: 0, z: 0 };
        } else {
          if (pos.x > gate.x + 0.03) {
            phase = "returnBehind";
            settle = 0;
          }

          if (phase === "returnBehind") {
            const safeY = clamp(gate.y + 0.62, 0.45, 2.55);
            const zClear = Math.abs(pos.z - gate.z) > 0.52 || Math.abs(pos.y - gate.y) > 0.42;
