          const distXZ = Math.hypot(pos.x - pad.x, pos.z - pad.z);
          const predDistXZ = Math.hypot(pos.x + v.x * 0.20 - pad.x, pos.z + v.z * 0.20 - pad.z);
          const speedXZ = Math.hypot(v.x, v.z);
