      const ex = clamp(target.x - pos.x, -0.85, 0.85);
      const ey = clamp(target.y - pos.y, -0.80, 0.80);
      const ez = clamp(target.z - pos.z, -0.85, 0.85);

      if (Math.abs(ex) < 0.35) {
        ix = clamp(ix + ex * dt, -0.45, 0.45);
      } else {
        ix *= 0.98;
      }
      if (Math.abs(ey) < 0.35) {
        iy = clamp(iy + ey * dt, -0.45, 0.45);
      } else {
        iy *= 0.98;
      }
      if (Math.abs(ez) < 0.35) {
        iz = clamp(iz + ez * dt, -0.45, 0.45);
      } else {
        iz *= 0.98;
      }

      const cy = Math.cos(obs.att.yaw);
      const sy = Math.sin(obs.att.yaw);
      const cr = Math.cos(obs.att.roll);
      const sr = Math.sin(obs.att.roll);
      const cp = Math.cos(obs.att.pitch);
      const sp = Math.sin(obs.att.pitch);

