      const axActual = b0Est * estHoverThrust * dirX;
      const azActual = b0Est * estHoverThrust * dirZ;

      const kpX = 14.5, kdX = 7.6, kiX = 3.0;
      const kpZ = 16.5, kdZ = 8.2, kiZ = 3.5;
      const kDist = 0.90;
      const kAtt = 0.42;

      const axEq = -kDist * dxEst + kiX * ix;
      const azEq = -kDist * dzEst + kiZ * iz;

      const axCmd =
        kpX * ex +
        kdX * (velTarget.x - v.x) +
        0.55 * v.x +
        axEq -
        kAtt * (axActual - axEq);

      const azCmd =
        kpZ * ez +
        kdZ * (velTarget.z - v.z) +
        0.55 * v.z +
