        const pitch = clamp(Math.atan2(af, ayCmd), -maxTilt, maxTilt);
        const roll = clamp(-Math.atan2(ar, ayCmd), -maxTilt, maxTilt);

        let thrust = ayCmd / (b0Est * Math.max(0.55, dirY));
