    const cy = Math.cos(obs.att.yaw), sy = Math.sin(obs.att.yaw);
    const cr = Math.cos(obs.att.roll), sr = Math.sin(obs.att.roll);
    const cp = Math.cos(obs.att.pitch), sp = Math.sin(obs.att.pitch);
    const bodyX = sp * cr, bodyZ = -sr;
    const dirX = cy * bodyX + sy * bodyZ, dirY = cp * cr, dirZ = -sy * bodyX + cy * bodyZ;

    if (obs.t > 0.015) {
      const axRaw = (obs.vel.x - prevObsVel.x) / dt;
      const ayRaw = (obs.vel.y - prevObsVel.y) / dt;
      const azRaw = (obs.vel.z - prevObsVel.z) / dt;
      const curCmdX = 0.5 * (prevCmd.x + b0Est * thrustEst * dirX - 0.55 * v.x);
      const curCmdY = 0.5 * (prevCmd.y + b0Est * thrustEst * dirY);
      const curCmdZ = 0.5 * (prevCmd.z + b0Est * thrustEst * dirZ - 0.55 * v.z);
      dxEst = clamp(dxEst + opts.alpha * (axRaw - curCmdX - dxEst), -7.5, 7.5);
      dzEst = clamp(dzEst + opts.alpha * (azRaw - curCmdZ - dzEst), -7.5, 7.5);
