    prevCmd.y = b0Est * thrustEst * dirY;
    prevCmd.z = b0Est * thrustEst * dirZ - 0.55 * v.z;

    if (step % 50 === 0) {
      console.log(`  t=${obs.t.toFixed(2)} g=${obs.gateIndex} ph=${phase} pos=(${state.pos.x.toFixed(2)},${state.pos.y.toFixed(2)},${state.pos.z.toFixed(2)}) dz=${obs.nextGate ? (state.pos.z - obs.nextGate.centre.z).toFixed(3) : (state.pos.z - PAD.centre.z).toFixed(3)}`);
